package cn.binbin.crm;

import java.net.URI;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSenderImpl;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class RecoveryService {
    private record Delivery(UUID id,String token,String email) {}
    private final NamedParameterJdbcTemplate db;private final TransactionTemplate tx;private final AuthService auth;private final JavaMailSenderImpl sender;private final String from,base;private final boolean enabled;
    public RecoveryService(NamedParameterJdbcTemplate db,TransactionTemplate tx,AuthService auth,@Value("${CRM_SMTP_HOST:}") String host,@Value("${CRM_SMTP_PORT:587}") int port,@Value("${CRM_SMTP_USER:}") String user,@Value("${CRM_SMTP_PASSWORD:}") String password,@Value("${CRM_SMTP_FROM:}") String from,@Value("${CRM_SMTP_TLS:true}") boolean tls,@Value("${CRM_SMTP_SSL:false}") boolean ssl,@Value("${CRM_ISOLATED_ACCEPTANCE:false}") boolean isolated,@Value("${CRM_PUBLIC_BASE_URL:https://crm-java-api-crm-test.up.railway.app}") String base){
        this.db=db;this.tx=tx;this.auth=auth;this.from=from;this.base=base;enabled=!host.isBlank()&&!from.isBlank();URI uri=URI.create(base);if(uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null||!uri.getRawPath().isEmpty()||(!"https".equals(uri.getScheme())&&!isolated))throw new IllegalArgumentException("Recovery URL invalid");if(enabled&&!tls&&!ssl&&!isolated)throw new IllegalArgumentException("SMTP TLS required");
        sender=new JavaMailSenderImpl();sender.setHost(host);sender.setPort(port);sender.setUsername(user);sender.setPassword(password);var p=sender.getJavaMailProperties();p.setProperty("mail.smtp.auth",String.valueOf(!user.isBlank()));p.setProperty("mail.smtp.starttls.enable",String.valueOf(tls));p.setProperty("mail.smtp.starttls.required",String.valueOf(tls));p.setProperty("mail.smtp.ssl.enable",String.valueOf(ssl));p.setProperty("mail.smtp.ssl.checkserveridentity","true");p.setProperty("mail.smtp.connectiontimeout","5000");p.setProperty("mail.smtp.timeout","5000");p.setProperty("mail.smtp.writetimeout","5000");
    }
    public boolean enabled(){return enabled;}
    public void bind(AuthService.Session s,UUID user,String email,long expectedVersion,String reason,UUID trace){auth.platform(s);tx.executeWithoutResult(status->{var existing=db.queryForList("SELECT auth_version FROM iam_user WHERE id=:id FOR UPDATE",Map.of("id",user));if(existing.isEmpty())throw ApiError.missing();var row=existing.getFirst();if(((Number)row.get("auth_version")).longValue()!=expectedVersion)throw ApiError.conflict("账号已变化，请刷新后绑定");db.update("UPDATE iam_user SET recovery_email=:email,recovery_email_verified_at=now(),auth_version=auth_version+1 WHERE id=:id",Map.of("email",email.strip().toLowerCase(Locale.ROOT),"id",user));db.update("UPDATE auth_password_reset SET used_at=coalesce(used_at,now()) WHERE user_id=:id",Map.of("id",user));db.update("INSERT INTO iam_audit(id,user_id,action,target_id,trace_id) VALUES(:id,:user,'RECOVERY_EMAIL_BOUND',:target,:trace)",Map.of("id",UUID.randomUUID(),"user",s.userId(),"target",user,"trace",trace));});}
    public void request(String raw,UUID trace){String username=raw.strip().toLowerCase(Locale.ROOT);Delivery delivery=tx.execute(status->{String hash=Crypto.hash("reset:"+username);db.update("INSERT INTO auth_reset_limit(key_hash) VALUES(:key) ON CONFLICT DO NOTHING",Map.of("key",hash));var limit=db.queryForMap("SELECT * FROM auth_reset_limit WHERE key_hash=:key FOR UPDATE",Map.of("key",hash));boolean expired=((Timestamp)limit.get("window_at")).toInstant().isBefore(Instant.now().minusSeconds(900));int attempts=expired?0:((Number)limit.get("requests")).intValue();if(attempts>=5)return null;db.update("UPDATE auth_reset_limit SET requests=:count,window_at=CASE WHEN :expired THEN now() ELSE window_at END WHERE key_hash=:key",Map.of("key",hash,"count",attempts+1,"expired",expired));
        var users=db.queryForList("SELECT id,recovery_email,auth_version FROM iam_user WHERE username=:name AND status='ACTIVE' AND recovery_email_verified_at IS NOT NULL",Map.of("name",username));if(users.isEmpty()||!enabled)return null;var user=users.getFirst();String token=Crypto.token();UUID id=UUID.randomUUID();db.update("DELETE FROM auth_password_reset WHERE user_id=:user AND (expires_at<now() OR used_at IS NOT NULL)",Map.of("user",user.get("id")));db.update("INSERT INTO auth_password_reset(id,user_id,token_hash,auth_version,expires_at) VALUES(:id,:user,:hash,:version,:end)",Map.of("id",id,"user",user.get("id"),"hash",Crypto.hash(token),"version",user.get("auth_version"),"end",Timestamp.from(Instant.now().plusSeconds(1800))));return new Delivery(id,token,(String)user.get("recovery_email"));});
        if(delivery!=null){try{var mail=new SimpleMailMessage();mail.setFrom(from);mail.setTo(delivery.email());mail.setSubject("彬彬 CRM · 重置登录密码");mail.setText("你申请了重置登录密码。请在30分钟内打开以下链接：\n"+base+"/?reset="+delivery.token()+"\n\n重置成功后，原登录会话会失效。如果并非本人操作，请忽略此邮件。");sender.send(mail);}catch(Exception e){db.update("UPDATE auth_password_reset SET used_at=now() WHERE id=:id",Map.of("id",delivery.id()));db.update("INSERT INTO sys_job_run(id,job_name,status,finished_at,error_code) VALUES(:id,'RECOVERY_MAIL','FAILED',now(),'MAIL_DELIVERY_FAILED')",Map.of("id",UUID.randomUUID()));}}
    }
    public void complete(String token,String next,UUID trace){auth.validatePassword(next);if(!token.matches("[A-Za-z0-9_-]{43}"))throw ApiError.bad("链接无效或已过期，请重新申请");tx.executeWithoutResult(status->{var rows=db.queryForList("SELECT r.id,r.user_id,r.auth_version,u.auth_version AS current_version,u.username FROM auth_password_reset r JOIN iam_user u ON u.id=r.user_id WHERE r.token_hash=:hash AND r.used_at IS NULL AND r.expires_at>now() AND u.status='ACTIVE' FOR UPDATE OF r,u",Map.of("hash",Crypto.hash(token)));if(rows.isEmpty())throw ApiError.bad("链接无效或已过期，请重新申请");var r=rows.getFirst();if(!r.get("auth_version").equals(r.get("current_version")))throw ApiError.bad("链接无效或已过期，请重新申请");db.update("UPDATE iam_user SET password_hash=:password,must_change_password=false,auth_version=auth_version+1 WHERE id=:user",Map.of("password",auth.passwordHash(next),"user",r.get("user_id")));db.update("UPDATE auth_password_reset SET used_at=coalesce(used_at,now()) WHERE user_id=:user",Map.of("user",r.get("user_id")));db.update("UPDATE auth_login_limit SET failures=0,blocked_until=NULL,updated_at=now() WHERE key_hash=:hash",Map.of("hash",Crypto.hash("login:"+r.get("username"))));db.update("INSERT INTO iam_audit(id,user_id,action,target_id,trace_id) VALUES(:id,:user,'PASSWORD_RECOVERED',:target,:trace)",Map.of("id",UUID.randomUUID(),"user",r.get("user_id"),"target",r.get("id"),"trace",trace));});}
}
